pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound to reasonable range to keep fuzzing effective
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Deploy an adversarial callee that reverts on receiving ETH
        Reverter reverter = new Reverter();
        address actor = address(reverter);

        // Give actor ETH and deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Record pre-state
        uint256 balanceBefore = address(c).balance;

        // Actor calls withdrawAll — it will attempt to send ETH to itself (the Reverter)
        vm.prank(actor);
        c.withdrawAll();

        // After withdrawAll, the contract's ETH balance should equal the sum of all remaining credits.
        // The Reverter has credit zero now, so balance should be zero (correct) or still have depositAmount (bug).
        uint256 balanceAfter = address(c).balance;
        uint256 reverterCredit = c.credit(actor);

        // General rule: contract balance equals total credit held by all users.
        // Since only the Reverter deposited, total credit = reverterCredit.
        assertTrue(balanceAfter == reverterCredit);
    }
}

