pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict to plausible values to avoid overflow in helper logic
        vm.assume(depositAmount > 0 && depositAmount < 1e30);
        vm.assume(withdrawAmount > 0 && withdrawAmount < 1e30);

        // Deploy adversarial callee that will reject ETH transfers
        Reverter reverter = new Reverter();
        address actor = address(reverter);

        // Fund the actor and have it deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Have the actor attempt to withdraw
        vm.prank(actor);
        c.withdrawAll();

        // After withdrawAll, the contract's internal balance should never exceed its ETH balance
        // (balance tracks ETH held, so balance <= address(c).balance always for correct contract)
        // We check a derived invariant: address(c).balance must be at least as large as the sum of all credits
        // credited to any remaining depositor. Since only one actor deposited, and withdrawAll zeroed its credit,
        // balance should match ETH balance. In buggy version, balance is decreased but ETH stays, so
        // address(c).balance > balance, violating balance <= address(c).balance.
        // We test: balance (internal) <= address(c).balance (actual ETH)
        uint256 bal = c.balance();
        assertTrue(bal <= address(c).balance);
    }
}

