        vm.deal(sender, withdrawAmount);
        vm.prank(sender);
        c.deposit{value: withdrawAmount}();

        // Transfer the helper's credit to the helper address (via a deposit that credits the helper)
        // Actually, we need credit for the helper. We'll deposit from the helper.
        vm.deal(address(revertee), withdrawAmount);
        vm.prank(address(revertee));
        c.deposit{value: withdrawAmount}();

        // Now the helper calls withdrawAll; the transfer to itself will revert
        vm.prank(address(revertee));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        bool reverted = !ok;

        // The invariant: contract ETH balance + sum of all individual credits == stored balance
        // Sum of credits: we only know sender and revertee
        uint256 totalCredit = 0;
        try c.credit(sender) returns (uint256 cr) { totalCredit += cr; } catch {}
        try c.credit(address(revertee)) returns (uint256 cr) { totalCredit += cr; } catch {}

        uint256 balanceStored = 0;
        try c.balance() returns (uint256 b) { balanceStored = b; } catch {}

        uint256 ethBalance = address(c).balance;

        assertTrue(ethBalance + totalCredit == balanceStored);
    }
