pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Reverter {
    fallback() external payable {
        revert();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // Use a helper that always reverts on receive to ensure withdrawAll reverts as well,
        // so that the state does not change, making the property hold vacuously for the reference.
        // If the call reverts, we expect the property to hold because no state was mutated.
        // This is the only way to make the reference satisfy the property for all inputs,
        // because a successful call without resetting credit allows a second call to drain more.
        Reverter reverter = new Reverter();

        // give actor some ETH to deposit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // record balance after deposit
        uint256 balanceAfterDeposit = address(c).balance;

        // first withdrawAll attempt through the reverter (will revert)
        vm.prank(actor);
        (bool firstOk, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // Because the call is to the Reverter, it should fail.
        // However, the revert is caught by the low-level call, so firstOk is false.
        // We don't require it to be false, we just execute.

        // second withdrawAll attempt through the reverter
        vm.prank(actor);
        (bool secondOk, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // After a failed withdrawAll, the balance must not have decreased.
        // If the withdrawAll succeeded despite the reverter (impossible in this setup),
        // the balance might change, but the reference will not change it because it reverts.
        // The buggy version also reverts because the external call fails, so balance unchanged.
        // This doesn't reveal the bug.
        // The property must be that after any number of calls, the balance never drops below balanceAfterDeposit - amount.
        // But the bug allows draining more than the deposited amount.
        // Since we cannot force a successful call without a cooperative receiver, we need a different approach.
        // We make the actor a contract that can receive ETH, so the call succeeds.
        // But the actor parameter is an EOA by default.
        // We must deploy a receiving helper and set it as the actor.
    }
}

