pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 secondDepositAmount) public {
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.assume(secondDepositAmount > 0 && secondDepositAmount < 1 ether);
        address alice = address(1);
        vm.deal(alice, depositAmount + 1 ether);
        vm.prank(alice);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;
        uint256 creditBefore = c.credit(alice);
        assertTrue(creditBefore == depositAmount);

        vm.prank(alice);
        c.withdrawAll();

        uint256 balanceAfterWithdraw = address(c).balance;
        uint256 creditAfterWithdraw = c.credit(alice);
        // After withdrawAll, the correct implementation zeroes Alice's credit,
        // while the buggy version leaves it as the original depositAmount.
        // We now have a second depositor (Bob) make a deposit.
        address bob = address(2);
        vm.deal(bob, secondDepositAmount + 1 ether);
        vm.prank(bob);
        c.deposit{value: secondDepositAmount}();

        uint256 balanceAfterSecondDeposit = address(c).balance;
        // In the correct version, total liabilities are exactly Bob's deposit
        // (since Alice's credit is zero). In the buggy version, Alice's credit
        // is still positive (equal to depositAmount), causing total recorded
        // credit to exceed the actual contract balance when compared to the
        // original balance before her withdrawal. The invariant:
        // balanceAfterSecondDeposit - (credit(alice) + credit(bob))
        // equals balanceBefore - (depositAmount + 0) in correct version (zero).
        // In the buggy version, the left side is negative because Alice's stale
        // credit inflates total liabilities. The specific numeric check that
        // holds in the correct version but fails in the buggy one:
        // balanceAfterSecondDeposit >= credit(alice) + credit(bob)
        // The correct version satisfies this because credit(alice)==0 and
        // credit(bob)==secondDepositAmount, and balance = secondDepositAmount.
        // The buggy version: balance = secondDepositAmount, credit(alice)=depositAmount,
        // credit(bob)=secondDepositAmount, so total = depositAmount+secondDepositAmount > balance.
        assertTrue(address(c).balance >= c.credit(alice) + c.credit(bob));
    }
}

